/* Priveo's header scripts. Generated by scripts/design/sync-priveo.mjs from web-priveo-sante@d9ae3c4: do not edit. */
/* ---- header_js.js ---- */
(function () {
  'use strict';

  const BREAKPOINT = 1200;

  let header = null;
  let overlay = null;
  let breakinClone = null;
  let isMobile = false;
  let resizeTimer;

  /* ── Overlay ── */

  function createOverlay() {
    overlay = document.createElement('div');
    overlay.className = 'header-overlay';
    document.body.appendChild(overlay);

    overlay.addEventListener('click', () => {
      header.querySelectorAll('.header__dropdown.is-widget-open').forEach((dd) => {
        const btn = dd.querySelector('button[aria-expanded="true"]');
        if (btn) btn.click();
      });
      overlay.classList.remove('active');
    });
  }

  /* ── Mobile menu state (sets .menu-open on <html> as :has fallback) ── */

  function watchMobileMenu() {
    const nav = header.querySelector('.navigation');
    if (!nav) return;

    new MutationObserver(() => {
      if (window.innerWidth > BREAKPOINT) return;
      const open = nav.classList.contains('is-widget-open');
      document.documentElement.classList.toggle('menu-open', open);
      if (open) requestAnimationFrame(measureBreakinHeight);
    }).observe(nav, { attributes: true, attributeFilter: ['class'] });
  }

  /* ── Desktop dropdown overlay + positioning ──
     Watches both .is-widget-open (LI) and aria-expanded (button) for robustness. */

  function watchDropdowns() {
    header.querySelectorAll('.header__dropdown').forEach((dd) => {
      const update = () => {
        if (window.innerWidth <= BREAKPOINT) return;

        const btn = dd.querySelector('button');
        const isOpen = dd.classList.contains('is-widget-open') ||
                       btn?.getAttribute('aria-expanded') === 'true';

        if (isOpen) {
          overlay.classList.add('active');
          positionDropdown(dd);
        } else if (!header.querySelector('.header__dropdown.is-widget-open, .header__dropdown button[aria-expanded="true"]')) {
          overlay.classList.remove('active');
        }
      };

      new MutationObserver(update).observe(dd, {
        attributes: true,
        attributeFilter: ['class'],
      });

      const btn = dd.querySelector('button');
      if (btn) {
        new MutationObserver(update).observe(btn, {
          attributes: true,
          attributeFilter: ['aria-expanded'],
        });
      }
    });
  }

  function positionDropdown(dd) {
  const content = dd.querySelector('.navigation__submenu');
  if (!content) return;

  content.style.left = '';
  content.style.transform = '';

  requestAnimationFrame(() => {
    const container = header.querySelector('.header__container');
    const trigger = dd.querySelector('.navigation__submenu-toggle');
    if (!container || !trigger) return;

    const cRect = container.getBoundingClientRect();
    const tRect = trigger.getBoundingClientRect();

    content.style.left = `${tRect.left - cRect.left - 16}px`;

    // Viewport-bound: keep dropdown within 16px of viewport edges
    const rect = content.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;

    if (rect.right > vw - 16) {
      content.style.left = `${parseFloat(content.style.left) - (rect.right - vw + 16)}px`;
    } else if (rect.left < 16) {
      content.style.left = `${parseFloat(content.style.left) + (16 - rect.left)}px`;
    }
  });
}

  /* ── Breakin: clone source actions into <body> ── */

  function handleBreakin() {
    const source = header.querySelector('[data-breakin]');
    if (!source) return;

    if (isMobile && !breakinClone) {
      const li = document.createElement('li');
      li.className = 'breakin-container';

      const clone = source.cloneNode(true);
      clone.removeAttribute('data-breakin');
      clone.classList.remove('breakin-active');

      li.appendChild(clone);
      document.body.appendChild(li);
      breakinClone = li;

      // Measure breakin height once it's rendered, set CSS var for panel padding
      requestAnimationFrame(() => measureBreakinHeight());
    }

    if (isMobile) {
      source.classList.add('breakin-active');
    } else if (breakinClone) {
      breakinClone.remove();
      breakinClone = null;
      source.classList.remove('breakin-active');
    }
  }

  function measureBreakinHeight() {
    if (!breakinClone) return;
    // Temporarily override transform to measure the rendered height
    const prev = breakinClone.style.cssText;
    breakinClone.style.cssText = 'opacity:0;transform:none;pointer-events:none;position:fixed;left:0;right:0;bottom:0;';
    const h = breakinClone.offsetHeight;
    breakinClone.style.cssText = prev;
    // Add 24px buffer above the breakin for the last menu item
    document.documentElement.style.setProperty('--breakin-height', (h + 24) + 'px');
  }

  /* ── Breakpoint transitions ── */

  function checkBreakpoint() {
    const wasMobile = isMobile;
    isMobile = window.innerWidth <= BREAKPOINT;
    if (isMobile === wasMobile) return;

    handleBreakin();

    if (!isMobile) {
      document.documentElement.classList.remove('menu-open');
      overlay.classList.remove('active');

      const activeToggle = header.querySelector('.navigation__toggle.is-active');
      if (activeToggle) activeToggle.click();

      const openNav = header.querySelector('.navigation.is-widget-open');
      if (openNav) openNav.classList.remove('is-widget-open');
    }
  }

  /* ── Init ── */

  function init() {
    header = document.querySelector('.header');
    if (!header) return;

    createOverlay();
    checkBreakpoint();
    // The first frame can use a transient font/layout height. Keep panel
    // clearance aligned with the fully rendered buttons.
    if (document.fonts) {
      document.fonts.ready.then(() => requestAnimationFrame(measureBreakinHeight));
    }
    window.addEventListener('load', () => requestAnimationFrame(measureBreakinHeight), {once: true});

    setTimeout(() => {
      watchMobileMenu();
      watchDropdowns();
      if (isMobile) handleBreakin();
    }, 300);

    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        checkBreakpoint();
        if (isMobile) measureBreakinHeight();
      }, 150);
    });

    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      document.documentElement.classList.remove('menu-open');
      overlay.classList.remove('active');
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* ---- floating-header.js ---- */
/* Floating header bar: once the page has scrolled past the header's own
   height (+40px) the fixed page-builder header gets .pv-floating and the CSS in
   components/shell/styles/header-floating.css eases it into an inset rounded bar; hysteresis on the way back
   avoids flicker at the edge. Desktop only. */
(function () {
  'use strict';
  var hdr = document.getElementById('site-header');
  if (!hdr || hdr.__pvFloat) return;
  hdr.__pvFloat = true;
  var on = false, baseH = hdr.offsetHeight || 78;
  function apply() {
    if (window.innerWidth <= 1200) { if (on) { on = false; hdr.classList.remove('pv-floating'); } return; }
    var y = window.scrollY;
    if (!on && y > baseH + 40) { on = true; hdr.classList.add('pv-floating'); }
    else if (on && y < baseH - 8) { on = false; hdr.classList.remove('pv-floating'); }
  }
  function update() { apply(); }
  window.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', function () { if (!on) baseH = hdr.offsetHeight || baseH; update(); });
  apply();
})();

/* ---- site-interactions.js ---- */
/* Native Priveo menus, accordions and standalone Splide carousels. */
(function () {
  'use strict';

  function init() {
    const header = document.querySelector('.header');
    const nav = header?.querySelector('.header__menu');
    const toggles = header ? Array.from(header.querySelectorAll('.header__toggle')) : [];
    const dropdowns = header ? Array.from(header.querySelectorAll('.header__dropdown')) : [];
    const mobile = () => window.innerWidth <= 1200;
    const hoverCapable = () => window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    let opener = null;

    function dropdown(item, open) {
      item.classList.toggle('is-widget-open', open);
      item.classList.toggle('open', open);
      const button = item.querySelector('.navigation__submenu-toggle button');
      button?.setAttribute('aria-expanded', String(open));
      const panel = item.querySelector('.navigation__submenu');
      if (panel) panel.inert = !open;
    }
    function menu(open, restoreFocus = false) {
      if (!nav) return;
      nav.classList.toggle('is-widget-open', open);
      document.documentElement.classList.toggle('menu-open', open);
      toggles.forEach(button => {
        button.classList.toggle('is-active', open);
        button.setAttribute('aria-expanded', String(open));
      });
      if (!open) dropdowns.forEach(item => dropdown(item, false));
      if (open && mobile()) nav.querySelector('a[href],button')?.focus();
      if (restoreFocus) opener?.focus();
    }
    toggles.forEach(button => button.addEventListener('click', () => {
      const open = !nav?.classList.contains('is-widget-open');
      if (open) opener = button;
      menu(open, !open);
    }));
    dropdowns.forEach(item => {
      dropdown(item, false);
      const button = item.querySelector('.navigation__submenu-toggle button');
      item.querySelector('.navigation__submenu-toggle')?.addEventListener('click', event => {
        event.preventDefault();
        const open = !item.classList.contains('is-widget-open');
        dropdowns.forEach(other => dropdown(other, other === item && open));
      });
      // Desktop: hovering a dropdown item opens it; leaving closes it after a short grace delay.
      let leaveTimer = null;
      item.addEventListener('pointerenter', event => {
        if (mobile() || event.pointerType === 'touch' || !hoverCapable()) return;
        clearTimeout(leaveTimer);
        dropdowns.forEach(other => dropdown(other, other === item));
      });
      item.addEventListener('pointerleave', event => {
        if (mobile() || event.pointerType === 'touch' || !hoverCapable()) return;
        clearTimeout(leaveTimer);
        leaveTimer = setTimeout(() => {
          if (!item.contains(document.activeElement)) dropdown(item, false);
        }, 150);
      });
    });
    document.addEventListener('click', event => {
      if (!header?.contains(event.target)) {
        dropdowns.forEach(item => dropdown(item, false));
        if (mobile() && !event.target.closest('.breakin-container')) menu(false);
      } else if (event.target.closest('a[href]') && mobile()) menu(false);
    });
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        const active = dropdowns.find(item => item.classList.contains('is-widget-open'));
        dropdowns.forEach(item => dropdown(item, false));
        active?.querySelector('.navigation__submenu-toggle button')?.focus();
        if (mobile()) menu(false, true);
      }
      if (event.key !== 'Tab' || !mobile() || !nav?.classList.contains('is-widget-open')) return;
      const focusable = [...nav.querySelectorAll('a[href],button'), ...document.querySelectorAll('.breakin-container a[href],.breakin-container button')]
        .filter(element => element.getClientRects().length && !element.closest('[inert]'));
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && (document.activeElement === first || !focusable.includes(document.activeElement))) { event.preventDefault(); last?.focus(); }
      if (!event.shiftKey && (document.activeElement === last || !focusable.includes(document.activeElement))) { event.preventDefault(); first?.focus(); }
    });
    window.addEventListener('resize', () => { if (!mobile()) menu(false); });

    document.querySelectorAll('.accordion').forEach((accordion, groupIndex) => {
      const items = Array.from(accordion.children).filter(item => item.querySelector('.disclosure__trigger'));
      const controls = items.map(item => item.querySelector('.disclosure__trigger'));
      function open(index) {
        items.forEach((item, i) => {
          const active = i === index;
          item.classList.toggle('is-widget-open', active);
          controls[i].setAttribute('aria-expanded', String(active));
          const panel = item.querySelector('.disclosure__panel');
          if (panel) { panel.hidden = !active; panel.style.display = active ? 'block' : 'none'; }
        });
      }
      items.forEach((item, index) => {
        const control = controls[index], panel = item.querySelector('.disclosure__panel');
        control.id ||= `accordion-${groupIndex}-${index}-control`;
        if (panel) {
          panel.id ||= `accordion-${groupIndex}-${index}-panel`;
          panel.setAttribute('aria-labelledby', control.id);
          control.setAttribute('aria-controls', panel.id);
        }
        control.addEventListener('click', () => open(index));
        control.addEventListener('keydown', event => {
          if (['Enter', ' '].includes(event.key) && control.tagName !== 'BUTTON') { event.preventDefault(); open(index); }
          const next = event.key === 'ArrowDown' ? (index + 1) % items.length : event.key === 'ArrowUp' ? (index + items.length - 1) % items.length : event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : null;
          if (next !== null) { event.preventDefault(); controls[next].focus(); }
        });
      });
      if (items.length) open(Math.min(items.length - 1, Math.max(0, Number(accordion.dataset.expandItem) || 0)));
    });

    window.priveoSliders ||= new WeakMap();
    if (window.Splide) document.querySelectorAll('.splide[data-splide]').forEach(element => {
      if (window.priveoSliders.has(element)) return;
      const list = element.querySelector('.splide__list');
      if (!list) return;
      Array.from(list.children).forEach(slide => slide.classList.add('splide__slide'));
      const instance = new window.Splide(element, JSON.parse(element.dataset.splide));
      window.priveoSliders.set(element, instance);
      instance.mount();
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
